import{_ as t,o as n,c as s,ah as r}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Les événements","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/activites/evenements.md","filePath":"src/guide/activites/evenements.md"}'),i={name:"guide/activites/evenements.md"};function a(o,e,l,u,c,p){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="les-evenements" tabindex="-1">Les événements <a class="header-anchor" href="#les-evenements" aria-label="Permalink to &quot;Les événements&quot;">​</a></h1><p>NextBoxx organise des événements, gratuits ou payants. Tout compte personne peut s&#39;y inscrire ; le <strong>Chargé d&#39;événements</strong> les prépare et les suit.</p><h2 id="s-inscrire-a-un-evenement" tabindex="-1">S&#39;inscrire à un événement <a class="header-anchor" href="#s-inscrire-a-un-evenement" aria-label="Permalink to &quot;S&#39;inscrire à un événement&quot;">​</a></h2><p><strong>Activités → Mes événements</strong> liste les événements à venir et vos inscriptions. Vous pouvez aussi vous inscrire depuis le site NextBoxx : votre compte est alors créé, ou réutilisé, et le rôle <strong>Participant</strong> s&#39;ajoute à vos rôles. Ce rôle ne donne aucun accès à une formation.</p><p>Cliquez sur <strong>M&#39;inscrire</strong>. Le statut de votre inscription dit où vous en êtes :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Ce que cela signifie</th></tr></thead><tbody><tr><td><strong>Confirmée</strong></td><td>Votre place est confirmée</td></tr><tr><td><strong>En attente de paiement</strong></td><td>Votre place est réservée jusqu&#39;à la date limite de paiement. Sans paiement, l&#39;inscription est annulée et la place libérée</td></tr><tr><td><strong>Liste d&#39;attente</strong></td><td>L&#39;événement est complet ; vous serez prévenu dès qu&#39;une place se libère</td></tr><tr><td><strong>Annulée</strong></td><td>Annulée par vous, faute de paiement à temps, ou parce que l&#39;événement est annulé</td></tr></tbody></table><p>Quelques règles :</p><ul><li><strong>Un événement gratuit</strong> confirme votre inscription tout de suite, et accepte des inscrits jusqu&#39;à son début.</li><li><strong>Un événement payant</strong> émet une facture à l&#39;inscription, <strong>à régler avant la date limite</strong>, 48 heures avant le début. Le paiement complet confirme l&#39;inscription. Sans paiement complet à cette date, l&#39;inscription est annulée, la facture annulée par un avoir, et la place libérée. Les modalités de paiement figurent dans « Coordonnées de paiement ».</li><li>Une <strong>place libérée</strong> (ou une capacité relevée) passe au premier de la <strong>liste d&#39;attente</strong>, qui est prévenu, et qui reçoit sa facture si l&#39;événement est payant.</li><li>Les inscriptions sont refusées si l&#39;événement est fermé ou si vous êtes déjà inscrit. Un <strong>compte suspendu</strong> pour impayé ne peut pas s&#39;inscrire à un événement <strong>payant</strong> (un événement gratuit reste possible). Un <strong>compte organisation</strong> ne s&#39;inscrit pas : chaque participant le fait avec son compte personnel.</li></ul><h3 id="annuler-son-inscription" tabindex="-1">Annuler son inscription <a class="header-anchor" href="#annuler-son-inscription" aria-label="Permalink to &quot;Annuler son inscription&quot;">​</a></h3><p><strong>Annuler mon inscription</strong> libère votre place pour la personne suivante et annule une facture non réglée. Vous pouvez annuler depuis la liste d&#39;attente, pendant l&#39;attente de paiement, ou une inscription confirmée sur un événement <strong>gratuit</strong>. <strong>Une place déjà payée ne s&#39;annule pas</strong> depuis votre espace : contactez l&#39;équipe.</p><p>Si vous vous réinscrivez ensuite, votre inscription annulée est reprise avec une nouvelle facture.</p><h2 id="organiser-les-evenements" tabindex="-1">Organiser les événements <a class="header-anchor" href="#organiser-les-evenements" aria-label="Permalink to &quot;Organiser les événements&quot;">​</a></h2><p>Le Chargé d&#39;événements et l&#39;Administrateur gèrent <strong>Activités → Événements</strong>. La liste s&#39;organise en <strong>À venir</strong>, <strong>Passés</strong> et <strong>Annulés</strong>.</p><h3 id="creer-et-publier" tabindex="-1">Créer et publier <a class="header-anchor" href="#creer-et-publier" aria-label="Permalink to &quot;Créer et publier&quot;">​</a></h3><p><strong>Nouvel événement</strong> : intitulé, présentation (affichée sur le site NextBoxx et dans Kura), début, fin (facultative), lieu, <strong>places</strong> et <strong>tarif</strong> en FCFA (0 pour gratuit). Il est créé en <strong>brouillon</strong> et ne prend d&#39;inscription <strong>qu&#39;une fois publié</strong>.</p><ul><li><strong>Publier</strong> l&#39;affiche sur le site et dans Kura.</li><li>Les dates sont dans le futur et la fin après le début.</li><li>Dès qu&#39;il y a un inscrit, <strong>le tarif ne change plus</strong> et la capacité ne peut descendre sous le nombre de places prises. Relever la capacité donne ses places à la liste d&#39;attente.</li><li>Les inscrits ne sont <strong>pas prévenus</strong> des modifications.</li></ul><h3 id="suivre-les-inscrits" tabindex="-1">Suivre les inscrits <a class="header-anchor" href="#suivre-les-inscrits" aria-label="Permalink to &quot;Suivre les inscrits&quot;">​</a></h3><p>La fiche d&#39;un événement montre les places prises, la liste d&#39;attente, la date limite de paiement, et chaque inscrit avec son statut, sa date d&#39;inscription et sa <strong>facture</strong> (avec le reste dû). Le Chargé consulte les factures ; <strong>le Coordinateur enregistre les paiements</strong> (voir <a href="./../coordinateur/facturation.html">Facturation</a>). Les factures d&#39;événement n&#39;entrent ni dans le calendrier de facturation, ni dans les relances, ni dans les commissions, ni dans les tableaux de bord Direction et Reporting.</p><h3 id="annuler-un-evenement" tabindex="-1">Annuler un événement <a class="header-anchor" href="#annuler-un-evenement" aria-label="Permalink to &quot;Annuler un événement&quot;">​</a></h3><p><strong>Annuler l&#39;événement</strong> est possible tant qu&#39;il n&#39;a pas commencé, avec un <strong>motif communiqué aux inscrits</strong>. Chaque inscrit est annulé et prévenu ; ce qui a été payé est remboursé par un <strong>avoir</strong>, ce qui restait dû est annulé par un avoir.</p>',20)])])}const g=t(i,[["render",a]]);export{m as __pageData,g as default};
